var_name:			ds.b 41
			even
var_i:			dc.w 0
var_square_square:			dc.w 0
			dc.b 40			; capacity
var_counter_label:			ds.b 41
			even
var_j:			dc.w 0
			dc.b 40			; capacity
var_counter_describe_describe:			ds.b 41
			even
var_counter_steps_get_steps:			dc.w 0
p_square_rs:			dc.l 0
var_square_n:			dc.w 0
p_report_rs:			dc.l 0
			dc.b 40			; capacity
var_report_label:			ds.b 41
			even
			dc.b 40			; capacity
var_report_value:			ds.b 41
			even
p_counter_add_rs:			dc.l 0
var_counter_add_n:			dc.w 0
var_counter_total:			dc.l 0
p_counter_p_bump_rs:			dc.l 0
var_counter_p_steps:			dc.w 0
p_counter_steps_get_rs:			dc.l 0
p_counter_describe_rs:			dc.l 0
tmp0:			dc.w 0
tmp1:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			dc.b 40			; capacity
stmp1:			ds.b 41
			even
ltmp0:			dc.l 0
ltmp1:			dc.l 0
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_lta_tmp:	ds.b 12
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_squares		equ ntc_bss + 0		; 20 bytes
ntc_bss_size	equ 20
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
